SELECT conductor.Name AS conductor_name, orchestra.Orchestra AS orchestra_name, COUNT(*) AS total_orchestras FROM conductor INNER JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID GROUP BY conductor.Conductor_ID ORDER BY COUNT(*) DESC LIMIT 1
SELECT conductor.Name, orchestra.Orchestra FROM conductor JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID ORDER BY orchestra.Orchestra_ID DESC;
SELECT conductor.Name, orchestra.Orchestra FROM conductor INNER JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID WHERE orchestra.Year_of_Founded = (SELECT MAX(Orchestra.Founded) FROM orchestra)
SELECT Name FROM conductor JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID WHERE orchestra.Year_of_Founded = (SELECT Year_of_Founded FROM orchestra ORDER BY Year_of_Founded DESC LIMIT 1)
SELECT DISTINCT conductor.Name, orchestra.Record_Company FROM conductor JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID;
SELECT COUNT(DISTINCT orchestra.Orchestra_ID) AS total_orchestras FROM orchestra;
SELECT orchestra.Major_Record_Format FROM conductor INNER JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID ORDER BY orchestra.Year_of_Founded ASC;
SELECT o.Major_Record_Format, o.Year_of_Founded FROM orchestra o JOIN performance p ON o.Orchestra_ID = p.Orchestra_ID JOIN show s ON p.Show_ID = s.Show_ID ORDER BY o.Year_of_Founded ASC;
SELECT orchestra.Orchestra, conductor.Conductor_ID, conductor.Name, conductor.birthday, conductor.Nationality, orchestra.Year_of_Founded, orchestra.Major_Record_Format, performance.Type, performance.Date, performance.Official_ratings_(millions), performance.Weekly_rank, show.Result, show.Attendance FROM conductor JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID JOIN performance ON performance.Orchestra_ID = orchestra.Orchestra_ID JOIN show ON show.Performance_ID = performance.Performance_ID WHERE performance.Weekly_rank = (SELECT MAX(Weekly_rank) FROM performance) ORDER BY conductor.birthday ASC;
SELECT orchestra.Record_Company FROM orchestra INNER JOIN conductor ON orchestra.Conductor_ID = conductor.Conductor_ID ORDER BY orchestra.Year_of_Founded DESC;
SELECT orchestra.Orchestra FROM conductor JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID WHERE orchestra.Record_Company IS NULL;
SELECT orchestra.Orchestra FROM orchestra INNER JOIN performance ON orchestra.Orchestra_ID = performance.Orchestra_ID WHERE performance.Type = 'Performance' AND orchestra.Record_Company IS NULL;
SELECT orchestra.Record_Company FROM orchestra JOIN conductor ON orchestra.Conductor_ID = conductor.Conductor_ID WHERE orchestra.Year_of_Founded < 2003;
SELECT DISTINCT orchestra.Record_Company FROM orchestra JOIN conductor ON orchestra.Conductor_ID = conductor.Conductor_ID WHERE orchestra.Year_of_Founded > 2003;
SELECT COUNT(*) AS number_of_first_shows FROM show WHERE show.If_first_show = TRUE;
SELECT COUNT(*) FROM show WHERE If_first_show = TRUE
SELECT p.Type, s.Show_ID FROM performance p JOIN show s ON p.Performance_ID = s.Performance_ID WHERE p.Weekly_rank > 0 AND s.If_first_show = 0
SELECT Type FROM performance JOIN show ON performance.Performance_ID = show.Performance_ID WHERE Weekly_rank > 1 AND show.If_first_show = 'No' AND Show_ID IN (SELECT Show_ID FROM show WHERE Weekly_rank > 1)
SELECT DISTINCT o.state, p.state FROM Owners o JOIN Professionals p ON o.owner_id = p.professional_id AND o.state = p.state;
SELECT Owners.state FROM Owners INNER JOIN Dogs ON Dogs.owner_id = Owners.owner_id INNER JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code INNER JOIN Professionals ON Professionals.professional_id = Treatments.professional_id INNER JOIN Breeds ON Dogs.breed_code = Breeds.breed_code;
SELECT AVG(Dogs.age) FROM Dogs;
SELECT AVG(Dogs.age) FROM Dogs;
SELECT o.last_name, o.cell_number, p.professional_id FROM Owners o JOIN Professionals p ON o.owner_id = p.owner_id WHERE o.state = 'Indiana' OR o.state = 'IN' OR p.state = 'Indiana' OR p.state = 'IN' AND p.cell_number IS NOT NULL;
SELECT Professionals.professional_id, Professionals.last_name, Professionals.cell_number FROM Professionals JOIN Owners ON Owners.owner_id = Professionals.owner_id JOIN Dogs ON Dogs.owner_id = Owners.owner_id JOIN Sizes ON Dogs.size_code = Sizes.size_code JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code JOIN Dogs ON Dogs.dog_id = Treatments.dog_id JOIN Professionals ON Professionals.professional_id = Treatments.professional_id WHERE Professionals.state = 'Indiana' OR Professionals.cell_number IS NOT NULL AND Treatments.treatment_type_code = (SELECT treatment_type_code FROM Treatment_Types WHERE treatment_type_code = (SELECT treatment_type_code FROM Treatment_Types WHERE treatment_type_code = 'M' OR treatment_type_code = 'T'));
SELECT Dogs.name FROM Dogs WHERE Dogs.date_departed IS NULL OR Dogs.date_departed < (SELECT DATE_OF_TREATMENT FROM Treatments WHERE cost_of_treatment <= 1000)
