SELECT DISTINCT o.first_name FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id JOIN Professionals p ON d.professional_id = p.professional_id JOIN Treatment_Types t ON d.treatment_type_code = t.treatment_type_code WHERE d.name NOT IN ('dog name') AND d.adopted_yn = 'Y' AND p.role_code = 'professional' AND p.first_name = 'Professional'
SELECT DISTINCT o.first_name FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id JOIN Professionals p ON d.professional_id = p.professional_id JOIN Treatment_Types t ON d.treatment_type_code = t.treatment_type_code WHERE d.name NOT IN ('dog') AND p.role_code IN ('professional', 'owner')
SELECT Professionals.professional_id, Professionals.first_name, Professionals.last_name FROM Professionals INNER JOIN Dogs ON Dogs.owner_id = Professionals.owner_id WHERE Dogs.abandoned_yn = 'N' AND Dogs.date_of_birth IS NULL;
SELECT Dogs.id, Dogs.name, Professionals.first_name, Professionals.last_name FROM Dogs INNER JOIN Professionals ON Dogs.owner_id = Professionals.owner_id WHERE Dogs.abandoned_yn = 'N' AND Dogs.dog_id IS NOT NULL AND Professionals.email_address IS NOT NULL;
