SELECT p.professional_id, p.first_name, p.last_name, t.treatment_type_code, t.date_of_treatment, t.cost_of_treatment FROM Professionals p JOIN Treatments t ON p.professional_id = t.professional_id JOIN Dogs d ON t.dog_id = d.dog_id WHERE t.treatment_type_code = (SELECT treatment_type_code FROM Treatment_Types WHERE treatment_type_code IN ('2', '3')) AND t.date_of_treatment >= (SELECT date_of_treatment FROM Treatments WHERE treatment_type_code IN ('2', '3'))
SELECT breed_name FROM Breeds WHERE breed_code IN (SELECT Dogs.breed_code FROM Dogs WHERE Dogs.abandoned_yn = '1') GROUP BY breed_code ORDER BY breed_code ASC;
SELECT breed_name FROM Breeds WHERE breed_code IN (SELECT Dogs.breed_code FROM Dogs WHERE Dogs.abandoned_yn = '1' GROUP BY Dogs.breed_code HAVING COUNT(Dogs.breed_code) = 1)
SELECT Owners.owner_id, Owners.last_name, Charges.charge_amount FROM Owners JOIN Charges ON Owners.owner_id = Charges.charge_id WHERE Charges.charge_type = 'Treatment' AND Charges.charge_amount = (SELECT MAX(charge_amount) FROM Charges WHERE charge_type = 'Treatment') ORDER BY Owners.owner_id;
SELECT Dogs.owner_id, Owners.last_name FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id ORDER BY Dogs.owner_id ASC;
SELECT t.treatment_type_description, c.charge_amount FROM Treatment_Types t JOIN Charges c ON t.treatment_type_code = c.treatment_type_code JOIN Dogs d ON c.dog_id = d.dog_id JOIN Owners o ON d.owner_id = o.owner_id ORDER BY c.charge_amount ASC LIMIT 1;
SELECT treatment_type_description FROM Treatment_Types ORDER BY cost_of_treatment ASC LIMIT 1;
SELECT o.owner_id, o.zip_code FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id ORDER BY d.date_departed DESC LIMIT 1;
SELECT Dogs.owner_id, SUM(Dogs.date_departed) AS total_spent_money FROM Dogs JOIN Owners ON Dogs.owner_id = Owners.owner_id JOIN Treatments ON Dogs.dog_id = Treatments.dog_id JOIN Professionals ON Treatments.professional_id = Professionals.professional_id GROUP BY Dogs.owner_id, Treatments.treatment_type_code ORDER BY total_spent_money DESC LIMIT 1;
SELECT Professionals.professional_id, Professionals.first_name, Professionals.last_name, Professionals.email_address, Professionals.home_phone, Professionals.cell_number, Treatment_Types.treatment_type_description FROM Professionals JOIN Treatments ON Professionals.professional_id = Treatments.professional_id JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code WHERE Treatments.dog_id IS NOT NULL AND Professionals.role_code = 'Professional'
SELECT o.owner_id, d.name, t.treatment_type_code, t.date_of_treatment, t.cost_of_treatment FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id JOIN Treatments t ON d.dog_id = t.dog_id JOIN Treatment_Types t2 ON t.treatment_type_code = t2.treatment_type_code WHERE t2.treatment_type_code IN ('treatment_type_1', 'treatment_type_2')
SELECT p.first_name, p.last_name, p.email_address, p.home_phone, p.cell_number FROM Professionals p JOIN Treatments t ON t.professional_id = p.professional_id WHERE t.cost_of_treatment < (SELECT AVG(cost_of_treatment) FROM Charges);
SELECT o.first_name, o.last_name, o.street, o.city, o.state, o.zip_code, o.email_address, o.home_phone, o.cell_number, p.name FROM Professionals p JOIN Dogs d ON d.owner_id = p.owner_id JOIN Owners o ON d.owner_id = o.owner_id JOIN Treatment_Types t ON d.treatment_type_code = t.treatment_type_code JOIN Charges c ON d.dog_id = c.charge_id JOIN Sizes s ON d.size_code = s.size_code JOIN Breeds b ON d.breed_code = b.breed_code WHERE p.role_code = 'Professional' AND c.charge_amount < (SELECT AVG(cost_of_treatment) FROM Charges)
SELECT Dogs.date_of_birth, Professionals.first_name, Professionals.last_name FROM Dogs JOIN Professionals ON Dogs.owner_id = Professionals.owner_id JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code JOIN Charges ON Treatments.charge_type = Charges.charge_type JOIN Sizes ON Dogs.size_code = Sizes.size_code JOIN Breeds ON Dogs.breed_code = Breeds.breed_code JOIN Owners ON Dogs.owner_id = Owners.owner_id;
SELECT Dogs.name, Professionals.first_name, Professionals.last_name, Treatments.date_of_treatment FROM Dogs INNER JOIN Professionals ON Dogs.owner_id = Professionals.owner_id INNER JOIN Treatments ON Treatments.dog_id = Dogs.dog_id INNER JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code;
SELECT Dogs.name, Treatment_Types.treatment_type_description, Charges.charge_amount FROM Dogs JOIN Treatment_Types ON Dogs.breed_code = Treatment_Types.treatment_type_code JOIN Charges ON Charges.charge_id = Dogs.dog_id;
SELECT Dogs.name, Treatment_Types.treatment_type_description, Charges.charge_amount FROM Dogs INNER JOIN Charges ON Dogs.owner_id = Charges.charge_id INNER JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code;
SELECT Dogs.owner_id, Dogs.name, Sizes.size_description FROM Dogs INNER JOIN Sizes ON Dogs.size_code = Sizes.size_code;
SELECT Dogs.name, Dogs.weight FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id;
SELECT Dogs.name, Owners.first_name, Owners.last_name, Dogs.name FROM Dogs JOIN Owners ON Dogs.owner_id = Owners.owner_id WHERE Dogs.abandoned_yn = 'N';
SELECT Dogs.name, Owners.first_name, Owners.last_name, Owners.street, Owners.city, Owners.state, Owners.zip_code, Owners.email_address, Owners.home_phone, Owners.cell_number FROM Dogs JOIN Owners ON Dogs.owner_id = Owners.owner_id ORDER BY Dogs.name;
SELECT Dogs.name, Treatments.date_of_treatment FROM Dogs JOIN Treatments ON Dogs.dog_id = Treatments.dog_id JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code JOIN Professionals ON Treatments.professional_id = Professionals.professional_id WHERE Treatments.cost_of_treatment IS NOT NULL ORDER BY Treatments.date_of_treatment DESC;
SELECT Dogs.name, Treatments.date_of_treatment FROM Dogs INNER JOIN Treatments ON Dogs.dog_id = Treatments.dog_id;
SELECT o.first_name, d.name AS dog_name FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id;
SELECT Dogs.name, Owners.first_name FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id WHERE Owners.state = 'VA' AND Dogs.abandoned_yn = 'Y' ORDER BY Dogs.name LIMIT 1
SELECT d.date_departed, d.date_arrived, t.date_of_treatment FROM Dogs d JOIN Treatments t ON d.dog_id = t.dog_id;
SELECT d.date_departed, d.date_of_birth, d.name, d.gender, d.weight, d.date_of_birth, d.date_arrived, d.date_departed, d.date_of_birth, d.date_arrived, d.date_departed, d.date_of_birth, d.date_arrived, d.date_departed, d.date_of_birth, d.date_arrived, d.date_departed FROM Dogs d WHERE d.date_of_birth IS NOT NULL AND d.date_arrived IS NOT NULL AND d.date_departed IS NOT NULL ORDER BY d.date_departed;
SELECT Dogs.owner_id, Dogs.last_name FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id WHERE Dogs.age = (SELECT MIN(age) FROM Dogs)
SELECT Owners.last_name, Dogs.age FROM Dogs JOIN Owners ON Dogs.owner_id = Owners.owner_id ORDER BY Dogs.age DESC LIMIT 1;
SELECT o.email_address FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id JOIN Treatments t ON d.dog_id = t.dog_id JOIN Professionals p ON p.professional_id = t.professional_id WHERE o.state = 'HI' OR o.state = 'WI' AND p.state = 'HI' OR p.state = 'WI';
