SELECT MAX(charge_amount) FROM Charges;
SELECT charge_amount FROM Charges ORDER BY charge_amount DESC LIMIT 1
SELECT Professionals.first_name, Professionals.last_name, Professionals.email_address, Professionals.home_phone, Professionals.cell_number FROM Professionals INNER JOIN Owners ON Professionals.owner_id = Owners.owner_id;
SELECT o.first_name, o.last_name, p.email_address, p.home_phone, p.cell_number FROM Owners o JOIN Professionals p ON o.owner_id = p.owner_id;
SELECT Dogs.breed_code, Dogs.size_code, Treatments.treatment_type_code, Treatments.cost_of_treatment, Treatments.date_of_treatment FROM Dogs JOIN Treatments ON Dogs.dog_id = Treatments.dog_id;
SELECT DISTINCT breed_name, size_description FROM Dogs JOIN Sizes ON Dogs.size_code = Sizes.size_code JOIN Breeds ON Dogs.breed_code = Breeds.breed_code;
SELECT Professionals.first_name, Professionals.last_name, Treatments.date_of_treatment AS date_of_treatment FROM Professionals INNER JOIN Treatments ON Professionals.professional_id = Treatments.professional_id INNER JOIN Dogs ON Treatments.dog_id = Dogs.dog_id INNER JOIN Sizes ON Dogs.size_code = Sizes.size_code INNER JOIN Breeds ON Dogs.breed_code = Breeds.breed_code INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id INNER JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code;
SELECT Dogs.name, Treatment_Types.treatment_type_description FROM Dogs JOIN Treatment_Types ON Dogs.dog_id = Treatments.dog_id JOIN Professionals ON Dogs.owner_id = Professionals.owner_id JOIN Treatments ON Treatments.professional_id = Professionals.professional_id;
SELECT COUNT(*) FROM singer;
SELECT COUNT(*) AS count FROM singer;
SELECT Name FROM singer ORDER BY Birth_Year ASC
SELECT Name FROM singer ORDER BY Birth_Year ASC
SELECT Singer_ID, Birth_Year, Citizenship FROM singer;
SELECT singer.Birth_Year, singer.Citizenship FROM singer;
SELECT Name FROM singer WHERE Citizenship != 'French'
SELECT Name FROM singer WHERE Citizenship != 'French'
SELECT Name FROM singer WHERE Birth_Year <= 1948
SELECT Name FROM singer WHERE Birth_Year < 1948
SELECT Name FROM singer WHERE Birth_Year = (SELECT MIN(Birth_Year) FROM singer)
SELECT Name FROM singer WHERE Birth_Year = (SELECT MIN(Birth_Year) FROM singer)
SELECT Citizenship, COUNT(*) AS Number_of_Singers FROM singer GROUP BY Citizenship
SELECT Citizenship, COUNT(Singer_ID) AS Number_of_Singers FROM singer GROUP BY Citizenship;
SELECT Citizenship, COUNT(*) AS Most_Common_Citizenship FROM singer GROUP BY Citizenship ORDER BY COUNT(*) DESC;
SELECT DISTINCT Citizenship FROM singer JOIN song ON song.Singer_ID = singer.Singer_ID ORDER BY Citizenship ASC;
SELECT DISTINCT Citizenship, MAX(Net_Worth_Millions) AS Highest_Net_Worth FROM singer GROUP BY Citizenship;
SELECT Citizenship, MAX(Net_Worth_Millions) AS Highest_Net_Worth FROM singer GROUP BY Citizenship;
SELECT s.Name AS Song_Name, s.Highest_Position AS Highest_Position FROM song s JOIN singer s2 ON s.Singer_ID = s2.Singer_ID WHERE s.Highest_Position = (SELECT MAX(Highest_Position) FROM song)
SELECT DISTINCT s.Name, s.Highest_Position FROM singer s JOIN song s ON s.Singer_ID = song.Singer_ID WHERE s.Highest_Position = (SELECT MAX(Highest_Position) FROM song)
SELECT DISTINCT s.Name FROM singer s JOIN song s_song ON s.Singer_ID = s_song.Singer_ID WHERE s_song.Sales > 3000000;
SELECT DISTINCT Name FROM singer WHERE Net_Worth_Millions > 300000;
SELECT Name FROM singer WHERE Singer_ID IN (SELECT Singer_ID FROM song WHERE Sales > 0)
SELECT Name FROM singer WHERE Singer_ID IN (SELECT Singer_ID FROM song WHERE Sales > 0 AND Song_ID IN (SELECT Song_ID FROM song WHERE Sales > 0 AND Highest_Position = 1))
SELECT singer.Name, MAX(song.Highest_Position) AS max_highest_position FROM singer JOIN song ON song.Singer_ID = singer.Singer_ID;
SELECT singer.Name, MAX(song.Highest_Position) AS MaxHighestPosition FROM singer INNER JOIN song ON singer.Singer_ID = song.Singer_ID GROUP BY singer.Name
SELECT Name FROM singer WHERE Singer_ID NOT IN (SELECT Singer_ID FROM song WHERE Sales IS NULL)
SELECT s.Name AS sname FROM singer s JOIN song s ON s.Singer_ID = song.Singer_ID WHERE song.Sales IS NULL;
SELECT singer.Citizenship FROM singer INNER JOIN song ON singer.Singer_ID = song.Singer_ID WHERE song.Highest_Position IS NOT NULL AND singer.Birth_Year < 1945;
SELECT Citizenship FROM singer JOIN song ON song.Singer_ID = singer.Singer_ID WHERE Birth_Year < 1945;
